import { randomBytes } from "node:crypto";

import { and, eq } from "drizzle-orm";

import type { ApplicationDatabaseClient } from "../database/database.server";
import {
  passwordCredentials,
  sessions,
  users,
} from "../database/schema.server";
import {
  createDummyPasswordHash,
  hashPassword,
  verifyPassword,
} from "./password.server";
import { PersistentRateLimiter } from "./rate-limiter.server";
import { deriveCsrfToken, hashOpaqueToken, safelyEqual } from "./token.server";

const IDLE_SESSION_MS = 5 * 24 * 60 * 60 * 1_000;
const ABSOLUTE_SESSION_MS = 90 * 24 * 60 * 60 * 1_000;
const LOGIN_FAILURE_WINDOW_MS = 15 * 60 * 1_000;
const PASSWORD_CHANGE_FAILURE_WINDOW_MS = 15 * 60 * 1_000;
const REGISTRATION_WINDOW_MS = 60 * 60 * 1_000;

type CredentialUser = Pick<
  typeof users.$inferSelect,
  "id" | "usernameNormalized"
> &
  Pick<typeof passwordCredentials.$inferSelect, "passwordHash">;

export type AuthenticatedSession = {
  absoluteExpiresAt: Date;
  csrfToken: string;
  token: string;
  user: {
    id: number;
    username: string;
  };
};

export type IssuedSession = AuthenticatedSession;

export type RegistrationResult =
  | { error: "duplicate-username"; ok: false }
  | { error: "rate-limited"; ok: false }
  | { ok: true; session: IssuedSession };

export type LoginResult =
  | { error: "invalid-credentials"; ok: false }
  | { error: "rate-limited"; ok: false }
  | { ok: true; session: IssuedSession };

export type PasswordChangeResult =
  | { error: "invalid-current-password"; ok: false }
  | { error: "invalid-session"; ok: false }
  | { error: "rate-limited"; ok: false }
  | { ok: true; session: IssuedSession };

function csrfTokenFor(sessionToken: string): string {
  return deriveCsrfToken(sessionToken, "authenticated-session");
}

function prepareIssuedSession(
  now: Date,
  user: AuthenticatedSession["user"],
  absoluteExpiresAt = new Date(now.getTime() + ABSOLUTE_SESSION_MS),
): {
  persisted: typeof sessions.$inferInsert;
  session: IssuedSession;
} {
  const token = randomBytes(32).toString("base64url");
  const idleExpiresAt = new Date(
    Math.min(now.getTime() + IDLE_SESSION_MS, absoluteExpiresAt.getTime()),
  );

  return {
    persisted: {
      absoluteExpiresAt: absoluteExpiresAt.toISOString(),
      createdAt: now.toISOString(),
      idleExpiresAt: idleExpiresAt.toISOString(),
      lastSeenAt: now.toISOString(),
      tokenHash: hashOpaqueToken(token),
      userId: user.id,
    },
    session: {
      absoluteExpiresAt,
      csrfToken: csrfTokenFor(token),
      token,
      user,
    },
  };
}

function isUniqueConstraint(error: unknown): boolean {
  return (
    error instanceof Error &&
    "code" in error &&
    error.code === "SQLITE_CONSTRAINT_UNIQUE"
  );
}

export class AuthenticationService {
  readonly #database: ApplicationDatabaseClient;
  readonly #now: () => Date;
  readonly #rateLimiter: PersistentRateLimiter;

  constructor(
    database: ApplicationDatabaseClient,
    now: () => Date = () => new Date(),
  ) {
    this.#database = database;
    this.#now = now;
    this.#rateLimiter = new PersistentRateLimiter(database, now);
  }

  async register(
    usernameNormalized: string,
    password: string,
    clientIp: string,
  ): Promise<RegistrationResult> {
    if (
      !this.#rateLimiter.consume(
        "registration",
        clientIp,
        5,
        REGISTRATION_WINDOW_MS,
      )
    ) {
      return { error: "rate-limited", ok: false };
    }

    const passwordHash = await hashPassword(password);
    const createdAt = this.#now().toISOString();

    try {
      const userId = this.#database.transaction((transaction) => {
        const user = transaction
          .insert(users)
          .values({ createdAt, usernameNormalized })
          .returning({ id: users.id })
          .get();

        transaction
          .insert(passwordCredentials)
          .values({
            passwordHash,
            updatedAt: createdAt,
            userId: user.id,
          })
          .run();

        return user.id;
      });

      return {
        ok: true,
        session: this.#issueSession(userId, usernameNormalized),
      };
    } catch (error) {
      if (isUniqueConstraint(error)) {
        return { error: "duplicate-username", ok: false };
      }

      throw error;
    }
  }

  async authenticate(
    token: string | undefined,
  ): Promise<AuthenticatedSession | undefined> {
    if (!token) {
      return undefined;
    }

    const tokenHash = hashOpaqueToken(token);
    const session = this.#database
      .select({
        absoluteExpiresAt: sessions.absoluteExpiresAt,
        idleExpiresAt: sessions.idleExpiresAt,
        tokenHash: sessions.tokenHash,
        userId: sessions.userId,
        usernameNormalized: users.usernameNormalized,
      })
      .from(sessions)
      .innerJoin(users, eq(users.id, sessions.userId))
      .where(eq(sessions.tokenHash, tokenHash))
      .get();

    if (!session) {
      return undefined;
    }

    const now = this.#now();
    const idleExpiresAt = new Date(session.idleExpiresAt);
    const absoluteExpiresAt = new Date(session.absoluteExpiresAt);

    if (idleExpiresAt <= now || absoluteExpiresAt <= now) {
      this.#database
        .delete(sessions)
        .where(eq(sessions.tokenHash, tokenHash))
        .run();
      return undefined;
    }

    const nextIdleExpiry = new Date(
      Math.min(now.getTime() + IDLE_SESSION_MS, absoluteExpiresAt.getTime()),
    );
    this.#database
      .update(sessions)
      .set({
        idleExpiresAt: nextIdleExpiry.toISOString(),
        lastSeenAt: now.toISOString(),
      })
      .where(eq(sessions.tokenHash, tokenHash))
      .run();

    return {
      absoluteExpiresAt,
      csrfToken: csrfTokenFor(token),
      token,
      user: {
        id: session.userId,
        username: session.usernameNormalized,
      },
    };
  }

  async changePassword(
    currentSession: AuthenticatedSession,
    currentPassword: string,
    nextPassword: string,
  ): Promise<PasswordChangeResult> {
    const rateLimitSubject = String(currentSession.user.id);
    if (
      !this.#rateLimiter.consume(
        "password-change-failure",
        rateLimitSubject,
        5,
        PASSWORD_CHANGE_FAILURE_WINDOW_MS,
      )
    ) {
      return { error: "rate-limited", ok: false };
    }

    const verification = await this.verifyCredentials(
      currentSession.user.username,
      currentPassword,
    );
    if (
      !verification.matches ||
      verification.user?.id !== currentSession.user.id
    ) {
      return { error: "invalid-current-password", ok: false };
    }

    const now = this.#now();
    const nextPasswordHash = await hashPassword(nextPassword);
    const nextSession = prepareIssuedSession(
      now,
      currentSession.user,
      currentSession.absoluteExpiresAt,
    );
    const currentTokenHash = hashOpaqueToken(currentSession.token);

    const rotated = this.#database.transaction((transaction) => {
      const persistedCurrentSession = transaction
        .select({ tokenHash: sessions.tokenHash })
        .from(sessions)
        .where(
          and(
            eq(sessions.tokenHash, currentTokenHash),
            eq(sessions.userId, currentSession.user.id),
          ),
        )
        .get();
      if (!persistedCurrentSession) return false;

      transaction
        .update(passwordCredentials)
        .set({
          passwordHash: nextPasswordHash,
          updatedAt: now.toISOString(),
        })
        .where(eq(passwordCredentials.userId, currentSession.user.id))
        .run();
      transaction
        .delete(sessions)
        .where(eq(sessions.userId, currentSession.user.id))
        .run();
      transaction
        .insert(sessions)
        .values(nextSession.persisted)
        .run();
      return true;
    });

    if (!rotated) {
      return { error: "invalid-session", ok: false };
    }

    this.#rateLimiter.clear("password-change-failure", rateLimitSubject);
    return { ok: true, session: nextSession.session };
  }

  async login(
    usernameNormalized: string,
    password: string,
    clientIp: string,
  ): Promise<LoginResult> {
    const rateLimitSubject = `${clientIp}\0${usernameNormalized}`;
    if (
      !this.#rateLimiter.consume(
        "login-failure",
        rateLimitSubject,
        10,
        LOGIN_FAILURE_WINDOW_MS,
      )
    ) {
      return { error: "rate-limited", ok: false };
    }

    const verification = await this.verifyCredentials(
      usernameNormalized,
      password,
    );

    if (!verification.matches || !verification.user) {
      return { error: "invalid-credentials", ok: false };
    }

    if (verification.needsRehash) {
      const replacement = await hashPassword(password);
      this.#database
        .update(passwordCredentials)
        .set({
          passwordHash: replacement,
          updatedAt: this.#now().toISOString(),
        })
        .where(eq(passwordCredentials.userId, verification.user.id))
        .run();
    }

    this.#rateLimiter.clear("login-failure", rateLimitSubject);

    return {
      ok: true,
      session: this.#issueSession(
        verification.user.id,
        verification.user.usernameNormalized,
      ),
    };
  }

  revokeSession(token: string): void {
    this.#database
      .delete(sessions)
      .where(eq(sessions.tokenHash, hashOpaqueToken(token)))
      .run();
  }

  verifyCsrfToken(sessionToken: string, candidate: string | undefined): boolean {
    if (!candidate) {
      return false;
    }

    return safelyEqual(csrfTokenFor(sessionToken), candidate);
  }

  #issueSession(userId: number, usernameNormalized: string): IssuedSession {
    const issued = prepareIssuedSession(this.#now(), {
      id: userId,
      username: usernameNormalized,
    });
    this.#database
      .insert(sessions)
      .values(issued.persisted)
      .run();
    return issued.session;
  }

  async verifyCredentials(
    usernameNormalized: string,
    password: string,
  ): Promise<{
    matches: boolean;
    needsRehash: boolean;
    user?: CredentialUser;
  }> {
    const user = this.#database
      .select({
        id: users.id,
        passwordHash: passwordCredentials.passwordHash,
        usernameNormalized: users.usernameNormalized,
      })
      .from(users)
      .innerJoin(
        passwordCredentials,
        eq(passwordCredentials.userId, users.id),
      )
      .where(eq(users.usernameNormalized, usernameNormalized))
      .get();
    const credential = user?.passwordHash ?? createDummyPasswordHash();
    const verification = await verifyPassword(password, credential);

    return {
      matches: Boolean(user) && verification.matches,
      needsRehash: verification.needsRehash,
      user,
    };
  }
}

app/auth/http.server.ts.source:
import type {
  AuthenticatedSession,
  IssuedSession,
} from "./authentication.server";
import type { PreAuthenticationCsrfSession } from "./pre-authentication-csrf.server";
import {
  getAuthenticationService,
  getPreAuthenticationCsrfService,
} from "./runtime.server";
import { applicationOrigin } from "../runtime.server";

const SESSION_COOKIE_NAME = "__Host-calorie_session";
const PRE_AUTHENTICATION_CSRF_COOKIE_NAME =
  "__Host-calorie_auth_csrf";

function parseCookies(header: string | null): Map<string, string> {
  const cookies = new Map<string, string>();

  for (const entry of header?.split(";") ?? []) {
    const separator = entry.indexOf("=");
    if (separator < 0) continue;

    const name = entry.slice(0, separator).trim();
    const value = entry.slice(separator + 1).trim();
    try {
      cookies.set(name, decodeURIComponent(value));
    } catch {
      // Ignore malformed cookie values at this external boundary.
    }
  }

  return cookies;
}

function getSessionToken(request: Request): string | undefined {
  return parseCookies(request.headers.get("Cookie")).get(SESSION_COOKIE_NAME);
}

function getPreAuthenticationCsrfToken(request: Request): string | undefined {
  return parseCookies(request.headers.get("Cookie")).get(
    PRE_AUTHENTICATION_CSRF_COOKIE_NAME,
  );
}

export function getClientIp(request: Request): string {
  return request.headers.get("X-Open-Calory-Client-IP") ?? "unknown";
}

export async function getAuthenticatedSession(
  request: Request,
): Promise<AuthenticatedSession | undefined> {
  return getAuthenticationService().authenticate(getSessionToken(request));
}

export function serializeSessionCookie(session: IssuedSession): string {
  return serializeHostCookie(
    SESSION_COOKIE_NAME,
    session.token,
    session.absoluteExpiresAt,
  );
}

export function serializeClearedSessionCookie(): string {
  return serializeHostCookie(SESSION_COOKIE_NAME, "", new Date(0));
}

function serializeHostCookie(
  name: string,
  value: string,
  expiresAt: Date,
): string {
  const maxAgeSeconds = Math.max(
    0,
    Math.floor((expiresAt.getTime() - Date.now()) / 1_000),
  );

  return [
    `${name}=${encodeURIComponent(value)}`,
    "Path=/",
    `Max-Age=${maxAgeSeconds}`,
    `Expires=${expiresAt.toUTCString()}`,
    "HttpOnly",
    "Secure",
    "SameSite=Lax",
  ].join("; ");
}

function serializePreAuthenticationCsrfCookie(
  session: PreAuthenticationCsrfSession,
): string {
  return serializeHostCookie(
    PRE_AUTHENTICATION_CSRF_COOKIE_NAME,
    session.token,
    session.expiresAt,
  );
}

function serializeClearedPreAuthenticationCsrfCookie(): string {
  return serializeHostCookie(
    PRE_AUTHENTICATION_CSRF_COOKIE_NAME,
    "",
    new Date(0),
  );
}

export function loadPreAuthenticationCsrf(request: Request): {
  csrfToken: string;
  headers?: Headers;
} {
  const service = getPreAuthenticationCsrfService();
  const current = service.resolve(getPreAuthenticationCsrfToken(request));
  if (current) return { csrfToken: current.csrfToken };

  const issued = service.issue();
  const headers = new Headers();
  headers.append("Set-Cookie", serializePreAuthenticationCsrfCookie(issued));
  return { csrfToken: issued.csrfToken, headers };
}

export function requirePreAuthenticationCsrf(
  request: Request,
  candidate: string | undefined,
): void {
  const token = getPreAuthenticationCsrfToken(request);
  if (!getPreAuthenticationCsrfService().verify(token, candidate)) {
    throw new Response("CSRF token rejected.", { status: 403 });
  }
}

export function authenticatedSessionHeaders(
  request: Request,
  session: IssuedSession,
): Headers {
  const preAuthenticationToken = getPreAuthenticationCsrfToken(request);
  getPreAuthenticationCsrfService().revoke(preAuthenticationToken);

  const headers = new Headers();
  headers.append("Set-Cookie", serializeSessionCookie(session));
  headers.append(
    "Set-Cookie",
    serializeClearedPreAuthenticationCsrfCookie(),
  );
  return headers;
}

export function requireValidOrigin(request: Request): void {
  if (request.headers.get("Origin") !== applicationOrigin()) {
    throw new Response("Request origin rejected.", { status: 403 });
  }
}

