app/food-entry/snapshot.server.ts.source:
import { z } from "zod";

import type {
  CatalogMeasurement,
  CatalogNutrition,
} from "../catalog/food-catalog.server";
import { foodEntries } from "../database/schema.server";

export { scaleCatalogNutrient } from "./nutrition";

type FoodEntryRow = typeof foodEntries.$inferSelect;

const catalogNutrientValueSchema = z.object({
  amount: z.number().finite().nonnegative(),
  fixedPointMultiplier: z.number().int().positive(),
});
const catalogNutritionSchema = z.object({
  carbohydrateMilligrams: catalogNutrientValueSchema.nullable(),
  energyMilliKcal: catalogNutrientValueSchema.nullable(),
  fatMilligrams: catalogNutrientValueSchema.nullable(),
  fiberMilligrams: catalogNutrientValueSchema.nullable(),
  proteinMilligrams: catalogNutrientValueSchema.nullable(),
  sodiumMilligrams: catalogNutrientValueSchema.nullable(),
  sugarMilligrams: catalogNutrientValueSchema.nullable(),
});
const catalogMeasurementSchema = z.object({
  baseQuantityMicrounits: z.number().int().positive(),
  id: z.string().min(1).max(128),
  label: z.string().min(1).max(200),
  unit: z.enum(["g", "ml"]),
});
const catalogMeasurementsSchema = z.array(catalogMeasurementSchema).min(1);

export function serializeCatalogNutrition(value: CatalogNutrition): string {
  return JSON.stringify(catalogNutritionSchema.parse(value));
}

export function parseCatalogNutrition(value: string): CatalogNutrition {
  return catalogNutritionSchema.parse(JSON.parse(value));
}

export function serializeCatalogMeasurements(
  value: CatalogMeasurement[],
): string {
  return JSON.stringify(catalogMeasurementsSchema.parse(value));
}

function parseCatalogMeasurements(row: FoodEntryRow): CatalogMeasurement[] {
  const parsed = z
    .array(catalogMeasurementSchema)
    .safeParse(JSON.parse(row.supportedMeasurements));
  if (parsed.success && parsed.data.length) return parsed.data;

  const measurements: CatalogMeasurement[] = [
    {
      baseQuantityMicrounits: row.selectedMeasurementBaseQuantityMicrounits,
      id: row.selectedMeasurementId,
      label: row.selectedMeasurementLabel,
      unit: row.selectedMeasurementUnit as "g" | "ml",
    },
  ];
  const baseId = `base:${row.authoritativeBaseUnit}:${row.authoritativeBaseQuantityMicrounits}`;
  if (!measurements.some((measurement) => measurement.id === baseId)) {
    measurements.push({
      baseQuantityMicrounits: row.authoritativeBaseQuantityMicrounits,
      id: baseId,
      label: `${row.authoritativeBaseQuantityMicrounits / 1_000_000} ${row.authoritativeBaseUnit}`,
      unit: row.authoritativeBaseUnit as "g" | "ml",
    });
  }
  return measurements;
}

export function foodEntrySnapshot(row: FoodEntryRow) {
  return {
    authoritativeBaseQuantityMicrounits:
      row.authoritativeBaseQuantityMicrounits,
    authoritativeBaseUnit: row.authoritativeBaseUnit,
    authoritativeNutrition: parseCatalogNutrition(row.authoritativeNutrition),
    barcode: row.barcode,
    brand: row.brand,
    carbohydrateMilligrams: row.carbohydrateMilligrams,
    createdAt: row.createdAt,
    dataType: row.sourceDataType,
    energyMilliKcal: row.energyMilliKcal,
    fatMilligrams: row.fatMilligrams,
    fiberMilligrams: row.fiberMilligrams,
    foodLogDate: row.foodLogDate,
    id: row.id,
    localEventTime: row.localEventTime,
    marketCountry: row.marketCountry,
    name: row.editedName ?? row.originalName,
    originalName: row.originalName,
    proteinMilligrams: row.proteinMilligrams,
    provider: row.provider,
    providerFoodId: row.providerFoodId,
    providerModifiedDate: row.providerModifiedDate,
    providerPublishedDate: row.providerPublishedDate,
    quantityMicrounits: row.quantityMicrounits,
    selectedMeasurementId: row.selectedMeasurementId,
    selectedMeasurementLabel: row.selectedMeasurementLabel,
    selectedMeasurementUnit: row.selectedMeasurementUnit,
    supportedMeasurements: parseCatalogMeasurements(row),
    sodiumMilligrams: row.sodiumMilligrams,
    sugarMilligrams: row.sugarMilligrams,
    updatedAt: row.updatedAt,
  };
}

app/food-log/date.ts.source:
export type FoodLogEventOrderKey = {
  createdAt: string;
  id: number;
  kind: "food" | "water";
  localEventTime: string;
};

const EVENT_KIND_TIE_BREAKER = { food: 1, water: 0 } as const;

const ISO_LOCAL_DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;
const ISO_LOCAL_MONTH_PATTERN = /^(\d{4})-(\d{2})$/;

function utcCalendarDate(year: number, monthIndex: number, day = 1): Date {
  const instant = new Date(0);
  instant.setUTCHours(0, 0, 0, 0);
  instant.setUTCFullYear(year, monthIndex, day);
  return instant;
}

function utcDateFromLocalDate(localDate: string): Date {
  const match = ISO_LOCAL_DATE_PATTERN.exec(localDate);
  if (!match) throw new Error("Invalid local date");
  return utcCalendarDate(
    Number(match[1]),
    Number(match[2]) - 1,
    Number(match[3]),
  );
}

function formatUtcLocalDate(instant: Date): string {
  return [
    String(instant.getUTCFullYear()).padStart(4, "0"),
    String(instant.getUTCMonth() + 1).padStart(2, "0"),
    String(instant.getUTCDate()).padStart(2, "0"),
  ].join("-");
}

export function parseIsoLocalDate(value: string): string | undefined {
  const match = ISO_LOCAL_DATE_PATTERN.exec(value);
  if (!match) return undefined;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const instant = utcCalendarDate(year, month - 1, day);

  if (
    instant.getUTCFullYear() !== year ||
    instant.getUTCMonth() !== month - 1 ||
    instant.getUTCDate() !== day
  ) {
    return undefined;
  }

  return value;
}

export function localDateAt(instant: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    day: "2-digit",
    month: "2-digit",
    timeZone,
    year: "numeric",
  }).formatToParts(instant);
  const value = (type: Intl.DateTimeFormatPartTypes) =>
    parts.find((part) => part.type === type)?.value;

  return `${value("year")}-${value("month")}-${value("day")}`;
}

export function addLocalDays(localDate: string, amount: number): string {
  const parsed = parseIsoLocalDate(localDate);
  if (!parsed || !Number.isInteger(amount)) throw new Error("Invalid local date");

  const instant = utcDateFromLocalDate(parsed);
  instant.setUTCDate(instant.getUTCDate() + amount);
  return formatUtcLocalDate(instant);
}

export function getNearbyLocalDates(selectedDate: string, today: string) {
  return Array.from({ length: 7 }, (_, index) =>
    localDayState(addLocalDays(selectedDate, index - 5), today, selectedDate),
  );
}

function shiftLocalMonth(localMonth: string, amount: number): string {
  const match = ISO_LOCAL_MONTH_PATTERN.exec(localMonth);
  if (!match || !Number.isInteger(amount)) throw new Error("Invalid local month");

  const instant = utcCalendarDate(
    Number(match[1]),
    Number(match[2]) - 1,
  );
  instant.setUTCMonth(instant.getUTCMonth() + amount);
  return `${String(instant.getUTCFullYear()).padStart(4, "0")}-${String(
    instant.getUTCMonth() + 1,
  ).padStart(2, "0")}`;
}

export function buildCalendarMonth(
  requestedMonth: string,
  today: string,
  selectedDate: string,
) {
  const todayMonth = today.slice(0, 7);
  const match = ISO_LOCAL_MONTH_PATTERN.exec(requestedMonth);
  const requestedMonthNumber = match ? Number(match[2]) : 0;
  const validRequestedMonth =
    Boolean(match) && requestedMonthNumber >= 1 && requestedMonthNumber <= 12;
  const month =
    validRequestedMonth && requestedMonth <= todayMonth
      ? requestedMonth
      : todayMonth;
  const [year, monthNumber] = month.split("-").map(Number);
  const first = utcCalendarDate(year, monthNumber - 1);
  const numberOfDays = utcCalendarDate(year, monthNumber, 0).getUTCDate();

  return {
    days: Array.from({ length: numberOfDays }, (_, index) => {
      const day = index + 1;
      const date = `${month}-${String(day).padStart(2, "0")}`;
      return { day, ...localDayState(date, today, selectedDate) };
    }),
    label: new Intl.DateTimeFormat("en-US", {
      month: "long",
      timeZone: "UTC",
      year: "numeric",
    }).format(first),
    leadingEmptyDays: first.getUTCDay(),
    month,
    nextMonth: month < todayMonth ? shiftLocalMonth(month, 1) : undefined,
    previousMonth: shiftLocalMonth(month, -1),
  };
}

function localDayState(date: string, today: string, selectedDate: string) {
  return {
    date,
    isFuture: date > today,
    isSelected: date === selectedDate,
    isToday: date === today,
  };
}

export function formatLocalDate(
  localDate: string,
  options: Intl.DateTimeFormatOptions,
): string {
  const parsed = parseIsoLocalDate(localDate);
  if (!parsed) throw new Error("Invalid local date");
  return new Intl.DateTimeFormat("en-US", {
    ...options,
    timeZone: "UTC",
  }).format(utcDateFromLocalDate(parsed));
}

export function compareFoodLogEventsDescending(
  left: FoodLogEventOrderKey,
  right: FoodLogEventOrderKey,
): number {
  return (
    right.localEventTime.localeCompare(left.localEventTime) ||
    right.createdAt.localeCompare(left.createdAt) ||
    right.id - left.id ||
    EVENT_KIND_TIE_BREAKER[right.kind] - EVENT_KIND_TIE_BREAKER[left.kind]
  );
}

app/food-log/event-time.server.ts.source:
import { sql } from "drizzle-orm";

import type { ApplicationDatabaseClient } from "../database/database.server";

type EventTimeDatabase = Pick<ApplicationDatabaseClient, "get">;

function localTimeAt(instant: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    hour: "2-digit",
    hourCycle: "h23",
    minute: "2-digit",
    second: "2-digit",
    timeZone,
  }).formatToParts(instant);
  const value = (type: Intl.DateTimeFormatPartTypes) =>
    parts.find((part) => part.type === type)?.value ?? "00";
  return `${value("hour")}:${value("minute")}:${value("second")}`;
}

function nextRetroactiveTime(latest: string | null): string {
  if (!latest) return "12:00:00";
  const [hour, minute, second] = latest.split(":").map(Number);
  const totalSeconds = hour * 3_600 + minute * 60 + second;
  if (totalSeconds >= 86_340) return latest;
  const next = totalSeconds + 60;
  return [Math.floor(next / 3_600), Math.floor((next % 3_600) / 60), next % 60]
    .map((value) => String(value).padStart(2, "0"))
    .join(":");
}

export function localEventTimeForNewFoodLogEvent(
  database: EventTimeDatabase,
  userId: number,
  foodLogDate: string,
  today: string,
  instant: Date,
  timeZone: string,
): string {
  if (foodLogDate === today) return localTimeAt(instant, timeZone);
  const latest = database.get<{ localEventTime: string | null }>(sql`
    SELECT MAX(local_event_time) AS localEventTime
    FROM (
      SELECT local_event_time
      FROM food_entries
      WHERE user_id = ${userId} AND food_log_date = ${foodLogDate}
      UNION ALL
      SELECT local_event_time
      FROM water_events
      WHERE user_id = ${userId} AND food_log_date = ${foodLogDate}
    )
  `);
  return nextRetroactiveTime(latest?.localEventTime ?? null);
}

export function nextUpdatedAt(now: Date, previous: string): string {
  const candidate = now.toISOString();
  if (candidate > previous) return candidate;
  return new Date(new Date(previous).getTime() + 1).toISOString();
}

