    .insert(users)
    .values({ createdAt, usernameNormalized: options.username })
    .returning({ id: users.id })
    .get().id;

  client
    .insert(userPreferences)
    .values({
      createdAt,
      displayUnits: "us",
      timeZone: options.timeZone,
      updatedAt: createdAt,
      userId,
    })
    .run();
