test("local dates remain stable at UTC boundaries and both DST transitions", () => {
  expect(
    localDateAt(new Date("2026-01-01T09:30:00.000Z"), "Pacific/Honolulu"),
  ).toBe("2025-12-31");
  expect(
    localDateAt(new Date("2026-01-01T09:30:00.000Z"), "Pacific/Kiritimati"),
